cd /workspace/out && cat > /tmp/srv.js <<'EOF'
const http=require('http'),fs=require('fs'),path=require('path');
http.createServer((req,res)=>{let p=req.url.split('?')[0]; if(p==='/')p='/index.html'; const f=path.join('/workspace/out',p); fs.readFile(f,(e,d)=>{if(e){res.writeHead(404);res.end('nf');}else{res.writeHead(200);res.end(d);}});}).listen(8099,()=>console.log('up'));
EOF
(node /tmp/srv.js >/tmp/srv.log 2>&1 &); sleep 2; for f in index.html ea-repository.html referenzarchitekturen.html; do echo "$f -> $(curl -s -o /dev/null -w '%{http_code}' http://localhost:8099/$f)"; done; curl -s http://localhost:8099/index.html | grep -o '<title>[^<]*</title>'; ls out 2>/dev/null; echo "checking out/_next"; ls /workspace/out/_next/static | head
